import {
    VlMap,
    VlMapBaseLayerGRBGray,
    VlMapFeaturesLayer,
    VlMapLayerCircleStyle,
    VlMapLayerStyle,
} from '@domg-wc/map';
// VlMapMultiselectActions staat in 2.20.0 niet in de index van @domg-wc/map (zie de notes). Importeer daarom het
// bestand van de component zelf: dat registreert vl-map-multiselect-actions.
import '@domg-wc/map/components/action/layer-action/select-action/multiselect-actions/vl-map-multiselect-actions.js';

// De features als GeoJSON-objecten, met coördinaten in Lambert 72 (EPSG:31370).
document.querySelector('vl-map-features-layer[name="layer-1"]').features = {
    type: 'FeatureCollection',
    features: [
        {
            type: 'Feature',
            id: 1,
            geometry: { type: 'Point', coordinates: [175000, 184000] },
        },
    ],
};
document.querySelector('vl-map-features-layer[name="layer-2"]').features = {
    type: 'FeatureCollection',
    features: [
        {
            type: 'Feature',
            id: 2,
            geometry: { type: 'Point', coordinates: [175000, 185000] },
        },
    ],
};
// layer-3 krijgt één Feature, geen FeatureCollection.
document.querySelector('vl-map-features-layer[name="layer-3"]').features = {
    type: 'Feature',
    id: 3,
    geometry: {
        type: 'Polygon',
        coordinates: [
            [
                [144000, 171000],
                [200000, 171000],
                [200000, 205000],
                [144000, 205000],
                [144000, 171000],
            ],
        ],
    },
};

// vl-map-multiselect-actions zoekt de lagen uit de property layers (hun name) enkel op wanneer het element aan de kaart
// gehangen wordt; layers achteraf zetten heeft geen effect. Maak het element daarom hier, zet layers en active, en
// hang het dan pas in vl-map.
const multiselectActions = document.createElement('vl-map-multiselect-actions');
multiselectActions.layers = ['layer-1', 'layer-2', 'layer-3'];
// De story zet de property active: die maakt de actie actief, ook als er al een andere actie van de kaart actief is.
// Het attribuut default-active activeert ze enkel als er nog geen andere actie actief is.
multiselectActions.active = true;
document.querySelector('vl-map').append(multiselectActions);

import {
    VlMap,
    VlMapBaseLayerGRBGray,
    VlMapFeaturesLayer,
    VlMapLayerCircleStyle,
    VlMapLayerSwitcher,
    VlMapSideSheet,
} from '@domg-wc/map';
// VlMapMultiselectActions staat in 2.20.0 niet in de index van @domg-wc/map (zie de notes). Importeer daarom het
// bestand van de component zelf: dat registreert vl-map-multiselect-actions.
import '@domg-wc/map/components/action/layer-action/select-action/multiselect-actions/vl-map-multiselect-actions.js';

// De actie en de layer-switcher zijn aan dezelfde twee lagen gekoppeld.
const layers = ['layer-1', 'layer-2'];

// De layer-switcher toont enkel de lagen uit layers.
document.querySelector('vl-map-layer-switcher').layers = layers;

// De features als GeoJSON-objecten, met coördinaten in Lambert 72 (EPSG:31370).
document.querySelector('vl-map-features-layer[name="layer-1"]').features = {
    type: 'FeatureCollection',
    features: [
        {
            type: 'Feature',
            id: 1,
            geometry: { type: 'Point', coordinates: [146055.0, 196908.0] },
        },
    ],
};
document.querySelector('vl-map-features-layer[name="layer-2"]').features = {
    type: 'FeatureCollection',
    features: [
        {
            type: 'Feature',
            id: 2,
            geometry: { type: 'Point', coordinates: [149055.0, 199908.0] },
        },
    ],
};

// vl-map-multiselect-actions zoekt de lagen uit de property layers (hun name) enkel op wanneer het element aan de kaart
// gehangen wordt; layers achteraf zetten heeft geen effect. Maak het element daarom hier, zet layers en active, en
// hang het dan pas in vl-map.
const multiselectActions = document.createElement('vl-map-multiselect-actions');
// default-active maakt de actie de standaardactie van de kaart: wordt een verborgen laag opnieuw zichtbaar, dan
// activeert de kaart ze daardoor terug. Zonder default-active blijft ze gedeactiveerd.
multiselectActions.setAttribute('default-active', '');
multiselectActions.layers = layers;
// De story zet ook de property active: die maakt de actie meteen actief, ook als er al een andere actie actief is.
multiselectActions.active = true;
document.querySelector('vl-map').append(multiselectActions);
